#pragma once
#include "MaterialDefinition.h"
#include <algorithm>
#include <tuple>

// Authoring declaration only. Compiled programs and their byte layouts are
// generated by AssetsPipeline; this header never creates GPU objects.
namespace ShaderDefinition {
inline bool Keys(const Json::Value& value,const std::set<std::string>& allowed,std::string& error) {
    if(!value.isObject()){error="Shader declaration must be an object";return false;}
    for(const auto& key:value.getMemberNames())if(!allowed.contains(key)){error="Unknown Shader declaration field: "+key;return false;}
    return true;
}
inline bool Parse(const QByteArray& source,Json::Value& output,std::string& error) {
    output={};error.clear();bool found=false;const std::string text=source.toStdString();
    for(std::size_t i=0;i+1<text.size();) {
        if(text[i]=='\"'||text[i]=='\'') {const char quote=text[i++];while(i<text.size()){if(text[i]=='\\'){i+=2;continue;}if(text[i++]==quote)break;}continue;}
        if(text[i]=='/'&&text[i+1]=='/'){const auto end=text.find('\n',i+2);i=end==std::string::npos?text.size():end+1;continue;}
        if(text[i]!='/'||text[i+1]!='*'){++i;continue;}
        const auto start=i+2,end=text.find("*/",start);const auto comment=text.substr(start,end==std::string::npos?text.size()-start:end-start);
        std::size_t offset=0;while(offset<comment.size()&&std::isspace(static_cast<unsigned char>(comment[offset])))++offset;
        const std::string marker="GameSproutShader";
        if(comment.compare(offset,marker.size(),marker)==0&&(offset+marker.size()==comment.size()||std::isspace(static_cast<unsigned char>(comment[offset+marker.size()]))||comment[offset+marker.size()]=='{')) {
            if(found||end==std::string::npos||comment.size()>256*1024){error="Shader requires one terminated GameSproutShader declaration, at most 256 KiB";return false;}
            if(!AssetArtifactIO::Parse(comment.substr(offset+marker.size()),output)){error="Invalid JSON in GameSproutShader declaration";return false;}found=true;
        }
        i=end==std::string::npos?text.size():end+2;
    }
    if(!found){error="Graphics .shader requires a GameSproutShader declaration with Vertex and Fragment entries";return false;}
    if(!Keys(output,{"Name","Passes"},error))return false;
    if(!output.isMember("Name"))output["Name"]="Shader";
    if(!output["Name"].isString()||output["Name"].asString().empty()||!output["Passes"].isArray()||output["Passes"].size()!=1){error="Shader requires Name and exactly one Forward Pass in the current renderer";return false;}
    auto& pass=output["Passes"][0];
    if(!Keys(pass,{"Name","LightMode","Vertex","Fragment","Cull","Blend","DepthTest","DepthWrite","DepthCompare"},error))return false;
    for(const char* entry:{"Name","Vertex","Fragment"})if(!pass[entry].isString()||!MaterialDefinition::Identifier(pass[entry].asString())){error=std::string("Shader Pass requires an identifier: ")+entry;return false;}
    if(pass.get("LightMode","Forward")!="Forward"){error="Only Forward Shader LightMode is currently supported";return false;}pass["LightMode"]="Forward";
    for(const auto& setting:std::initializer_list<std::tuple<const char*,const char*,std::set<std::string>>>{{"Cull","Back",{"Off","Front","Back"}},{"Blend","Opaque",{"Opaque","Alpha","PremultipliedAlpha"}},{"DepthCompare","LessEqual",{"Never","Less","Equal","LessEqual","Greater","NotEqual","GreaterEqual","Always"}}}) {
        const auto& [key,defaultValue,values]=setting;if(!pass.isMember(key))pass[key]=defaultValue;
        if(!pass[key].isString()||!values.contains(pass[key].asString())){error=std::string("Unsupported Shader Pass state: ")+key;return false;}
    }
    for(const char* key:{"DepthTest","DepthWrite"}) {if(!pass.isMember(key))pass[key]=true;if(!pass[key].isBool()){error=std::string("Shader Pass state must be boolean: ")+key;return false;}}
    return true;
}
inline const Json::Value* Property(const Json::Value& schema,const std::string& name) {
    for(const auto& property:schema["Properties"])if(property["Name"]==name)return &property;
    return nullptr;
}
inline bool ValueType(const std::string& reflected,std::string& type,unsigned& size) {
    if(reflected=="float"){type="Float";size=4;}else if(reflected=="int"){type="Int";size=4;}else if(reflected=="uint"){type="UInt";size=4;}
    else if(reflected=="vec2"){type="Float2";size=8;}else if(reflected=="vec3"){type="Float3";size=12;}else if(reflected=="vec4"){type="Float4";size=16;}else return false;
    return true;
}
inline bool MaterialMember(const Json::Value& schema,const std::string& name,const std::string& type) {
    if(const auto* property=Property(schema,name)) {
        const auto declared=(*property)["Type"].asString();
        if(type=="Float")return declared=="Float"||declared=="Range";
        if(type=="Int")return declared=="Int"||declared=="Toggle"||declared=="Enum";
        if(type=="UInt")return declared=="Toggle"||declared=="Enum";
        return type=="Float4"&&(declared=="Color"||declared=="Vector");
    }
    for(const auto& property:schema["Properties"])if(property["Type"]=="Texture"&&name==property["Name"].asString()+"ST")return type=="Float4";
    return false;
}
inline bool ProgramLayout(const Json::Value& reflection,const Json::Value& schema,bool vertex,Json::Value& output,std::string& error) {
    output=Json::Value(Json::objectValue);output["Uniforms"]=Json::Value(Json::arrayValue);output["Textures"]=Json::Value(Json::arrayValue);
    if(!reflection.isObject()||(!reflection["types"].isNull()&&!reflection["types"].isObject())){error="Invalid graphics Shader reflection";return false;}
    if(!reflection["entryPoints"].isArray()||reflection["entryPoints"].size()!=1
        ||reflection["entryPoints"][0]["mode"]!=(vertex?"vert":"frag")){error="Graphics Shader reflected entry point stage mismatch";return false;}
    for(const char* group:{"ubos","separate_images","separate_samplers"}) {
        const auto& resources=reflection[group];
        if(!resources.isNull()&&!resources.isArray()){error="Invalid graphics Shader resource list";return false;}
        const unsigned limit=std::string(group)=="ubos"?4:16;
        if(resources.size()>limit){error="Graphics Shader exceeds resource binding limits";return false;}
        std::set<unsigned> bindings;
        for(const auto& resource:resources) {
            const unsigned set=std::string(group)=="ubos"?(vertex?1:3):(vertex?0:2);
            if(!resource["set"].isUInt()||resource["set"].asUInt()!=set||!resource["binding"].isUInt()||!resource["array"].empty()
                ||!bindings.insert(resource["binding"].asUInt()).second){error="Invalid or duplicate graphics Shader bindings";return false;}
        }
        unsigned expected=0;for(unsigned binding:bindings)if(binding!=expected++){error="Graphics Shader bindings must be consecutive from zero";return false;}
    }
    for(const char* category:{"images","ssbos","textures","push_constants","subpass_inputs"})if(!reflection[category].empty()){error="Graphics Shader resource is not supported by GRHI: "+std::string(category);return false;}
    if(vertex&&!reflection["separate_images"].empty()){error="Vertex texture sampling is not supported by current GRHI";return false;}
    if(reflection["separate_images"].size()!=reflection["separate_samplers"].size()){error="Each material texture needs a paired sampler";return false;}
    for(const auto& texture:reflection["separate_images"]) {
        const auto name=texture["name"].asString();const auto* property=Property(schema,name);
        if(!property||(*property)["Type"]!="Texture"||texture["type"]!="texture2D"||!texture["array"].empty()){error="Shader texture must be a scalar Texture2D material property: "+name;return false;}
        Json::Value item;item["Name"]=name;item["Slot"]=texture["binding"];output["Textures"].append(item);
    }
    bool hasFrame=false;
    for(const auto& block:reflection["ubos"]) {
        const auto type=reflection["types"][block["type"].asString()];const auto& members=type["members"];
        if(!block["block_size"].isUInt()||!block["binding"].isUInt()||!members.isArray()){error="Invalid Shader uniform reflection";return false;}
        const auto rawSize=block["block_size"].asUInt(),slot=block["binding"].asUInt();
        if(rawSize==0||rawSize>16384||slot>=4){error="Shader uniform exceeds supported limits";return false;}
        Json::Value item;item["Slot"]=slot;item["Size"]=(rawSize+15u)&~15u;item["Members"]=Json::Value(Json::arrayValue);
        // DXC prefixes cbuffer names with "type." in SPIR-V reflection.
        // Identify the engine block by its exact name, never by register b0:
        // existing fragment b0 material blocks keep their authoring meaning.
        const auto blockName=block["name"].asString();
        if(blockName=="GameSproutFrame"||blockName=="type.GameSproutFrame") {
            if(hasFrame||rawSize!=64||members.size()!=4){error="GameSproutFrame must contain exactly four float4 values (64 bytes) once per stage";return false;}
            const char* names[]={"Time","CameraPosition","MainLightDirection","MainLightColor"};
            for(unsigned i=0;i<4;++i)if(members[i]["name"]!=names[i]||members[i]["type"]!="vec4"||
                !members[i]["offset"].isUInt()||members[i]["offset"].asUInt()!=i*16u||!members[i]["array"].empty()) {
                error="GameSproutFrame must declare float4 Time, CameraPosition, MainLightDirection, MainLightColor in this order";return false;
            }
            hasFrame=true;item["Source"]="Frame";
        }else if(vertex&&slot==0) {
            if(rawSize!=192||members.size()!=3){error="Vertex b0 must be GameSproutDraw with three column_major matrices (192 bytes)";return false;}
            const char* names[]={"Model","ViewProjection","NormalMatrix"};
            for(unsigned i=0;i<3;++i)if(members[i]["name"]!=names[i]||members[i]["type"]!="mat4"||(!members[i]["offset"].isUInt()||members[i]["offset"].asUInt()!=i*64u)||members[i]["matrix_stride"]!=16||!members[i].get("row_major",false).asBool()) {
                // DXC's HLSL column_major is represented as row_major SPIR-V
                // decoration because HLSL matrix indexing is transposed.
                error="GameSproutDraw must declare column_major Model, ViewProjection, NormalMatrix in this order";return false;
            }
            item["Source"]="Draw";
        }else {
            item["Source"]="Material";std::set<std::string> names;std::vector<std::pair<unsigned,unsigned>> ranges;
            for(const auto& member:members) {
                std::string valueType;unsigned size=0;const auto name=member["name"].asString();
                if(!member["offset"].isUInt()||!member["array"].empty()||!ValueType(member["type"].asString(),valueType,size)||!MaterialMember(schema,name,valueType)||!names.insert(name).second){error="Unsupported or undeclared material uniform: "+name;return false;}
                const unsigned offset=member["offset"].asUInt();if(offset%4||offset>rawSize||size>rawSize-offset){error="Material uniform exceeds its reflected block: "+name;return false;}
                for(const auto& range:ranges)if(offset<range.second&&offset+size>range.first){error="Overlapping material uniforms";return false;}ranges.push_back({offset,offset+size});
                Json::Value field;field["Name"]=name;field["Type"]=valueType;field["Offset"]=offset;item["Members"].append(field);
            }
        }
        output["Uniforms"].append(item);
    }
    std::set<unsigned> inputLocations;
    if(vertex)for(const auto& input:reflection["inputs"]) {
        if(!input["location"].isUInt()||input["location"].asUInt()>3){error="Custom mesh Shader inputs are Position0/Normal1/Color2/UV3";return false;}
        if(!inputLocations.insert(input["location"].asUInt()).second||!input["array"].empty()){error="Duplicate or array mesh Shader input";return false;}
        const char* expected[]={"vec3","vec3","vec4","vec2"};if(input["type"]!=expected[input["location"].asUInt()]){error="Custom mesh Shader input type mismatch";return false;}
    }
    for(const char* group:{"Uniforms","Textures"}) {
        std::vector<Json::Value> ordered;for(const auto& item:output[group])ordered.push_back(item);
        std::sort(ordered.begin(),ordered.end(),[](const auto& a,const auto& b){return a["Slot"].asUInt()<b["Slot"].asUInt();});
        output[group]=Json::Value(Json::arrayValue);for(auto& item:ordered)output[group].append(std::move(item));
    }
    return true;
}
inline bool ValidateLinkedPass(const Json::Value& pass,std::string& error) {
    const auto& vertex=pass["Vertex"]["Reflection"];
    const auto& fragment=pass["Fragment"]["Reflection"];
    if(!fragment["outputs"].isArray()||fragment["outputs"].size()!=1||!fragment["outputs"][0]["location"].isUInt()
        ||fragment["outputs"][0]["location"].asUInt()!=0||fragment["outputs"][0]["type"]!="vec4"||!fragment["outputs"][0]["array"].empty()) {
        error="Forward Fragment must output one float4 at SV_Target0; MRT is not supported";return false;
    }
    if(!fragment["inputs"].isNull()&&!fragment["inputs"].isArray()){error="Invalid Fragment interface reflection";return false;}
    std::set<unsigned> locations;
    for(const auto& input:fragment["inputs"]) {
        if(!input["location"].isUInt()||!locations.insert(input["location"].asUInt()).second){error="Invalid Fragment input location";return false;}
        bool matched=false;
        for(const auto& output:vertex["outputs"])if(input["location"]==output["location"]&&input["type"]==output["type"]&&input["array"]==output["array"]){matched=true;break;}
        if(!matched){error="Vertex/Fragment interface mismatch at location "+input["location"].asString();return false;}
    }
    std::map<std::string,std::string> types;
    for(const char* stage:{"Vertex","Fragment"})for(const auto& block:pass[stage]["Uniforms"])for(const auto& member:block["Members"]) {
        const auto name=member["Name"].asString(),type=member["Type"].asString();
        const auto [found,inserted]=types.emplace(name,type);if(!inserted&&found->second!=type){error="Material uniform has inconsistent stage types: "+name;return false;}
    }
    return true;
}

}
